def getDeploymentEvents(deploymentId, integrationId=None, eventType=None, level=None, occurredAtFrom=None, occurredAtTo=None, afterSequence=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0117000" if __import__("os").path.isdir("./environment_mix/0117000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_s = now_dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        raw = hashlib.sha1((prefix + ":" + now_s + ":" + str(time.time_ns())).encode("utf-8")).digest()
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s[:20]}"

    def _match_id(pat, val):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            v = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _log(api_requests, integration_id, status, http_status=None, error_code=None, error_message=None, deployment_id=None, latency_ms=None):
        row = {
            "id": _new_id("req"),
            "integration_id": integration_id,
            "tool_name": "getDeploymentEvents",
            "request_params": {
                "deploymentId": deploymentId,
                "integrationId": integrationId,
                "eventType": eventType,
                "level": level,
                "occurredAtFrom": occurredAtFrom,
                "occurredAtTo": occurredAtTo,
                "afterSequence": afterSequence,
                "sortOrder": sortOrder,
                "limit": limit,
                "cursor": cursor,
            },
            "deployment_id": deployment_id,
            "deployment_file_id": None,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) and latency_ms >= 0 else None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return row

    # Validate required params
    if not _match_id(r"^dpl_[0-9A-Z]{17,}$", deploymentId):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="deploymentId is invalid.")
        return _err("VALIDATION_ERROR", "deploymentId is invalid.")

    if integrationId is not None and not _match_id(r"^vint_[0-9A-Z]{17,}$", integrationId):
        reqs = _load("api_requests.json")
        _log(reqs, "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="integrationId is invalid.")
        return _err("VALIDATION_ERROR", "integrationId is invalid.")

    if eventType is not None and eventType not in ("state_change", "log", "warning", "error", "audit"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="eventType is invalid.")
        return _err("VALIDATION_ERROR", "eventType is invalid.")

    if level is not None and level not in ("debug", "info", "warn", "error"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="level is invalid.")
        return _err("VALIDATION_ERROR", "level is invalid.")

    dt_from = _parse_dt(occurredAtFrom, "occurredAtFrom") if occurredAtFrom is not None else None
    if isinstance(dt_from, dict) and "error" in dt_from:
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message=dt_from["error"]["message"])
        return dt_from

    dt_to = _parse_dt(occurredAtTo, "occurredAtTo") if occurredAtTo is not None else None
    if isinstance(dt_to, dict) and "error" in dt_to:
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message=dt_to["error"]["message"])
        return dt_to

    if dt_from and dt_to and dt_from > dt_to:
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="occurredAtFrom must be <= occurredAtTo.")
        return _err("VALIDATION_ERROR", "occurredAtFrom must be <= occurredAtTo.")

    if afterSequence is not None:
        if not isinstance(afterSequence, int) or afterSequence < 0:
            reqs = _load("api_requests.json")
            _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="afterSequence must be an integer >= 0.")
            return _err("VALIDATION_ERROR", "afterSequence must be an integer >= 0.")

    if sortOrder is None:
        sortOrder = "asc"
    if sortOrder not in ("asc", "desc"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="sortOrder is invalid.")
        return _err("VALIDATION_ERROR", "sortOrder is invalid.")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 500.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")

    if cursor is not None and not isinstance(cursor, str):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="cursor must be a string.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # IMPORTANT: Do NOT reject cursor + afterSequence; accept both (cursor is opaque paging token).
    # Resolve active integration context
    integrations = _load("vercel_integrations.json")
    active = [r for r in integrations if isinstance(r, dict) and r.get("status") == "active"]
    integ_row = None
    if integrationId is not None:
        for r in active:
            if r.get("id") == integrationId:
                integ_row = r
                break
    else:
        if active:
            integ_row = active[0]

    api_requests = _load("api_requests.json")

    if not integ_row:
        _log(api_requests, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="UNAUTHORIZED", error_message="No active integration available for this call.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No active integration available for this call.")

    # Scope check: deployment must belong to integration
    deployments = _load("deployments.json")
    dep = None
    for d in deployments:
        if isinstance(d, dict) and d.get("id") == deploymentId and d.get("integration_id") == integ_row["id"]:
            dep = d
            break

    if not dep:
        _log(api_requests, integ_row["id"], "error", error_code="NOT_FOUND", error_message="Deployment not found in this integration scope.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Deployment not found in this integration scope.")

    # Fetch/filter events
    events = _load("deployment_events.json")
    scoped = [e for e in events if isinstance(e, dict) and e.get("deployment_id") == deploymentId and e.get("integration_id") == integ_row["id"]]

    if eventType is not None:
        scoped = [e for e in scoped if e.get("event_type") == eventType]
    if level is not None:
        scoped = [e for e in scoped if e.get("level") == level]
    if dt_from is not None:
        scoped2 = []
        for e in scoped:
            odt = _parse_dt(e.get("occurred_at"), "occurred_at") if isinstance(e.get("occurred_at"), str) else None
            if isinstance(odt, datetime.datetime) and odt >= dt_from:
                scoped2.append(e)
        scoped = scoped2
    if dt_to is not None:
        scoped2 = []
        for e in scoped:
            odt = _parse_dt(e.get("occurred_at"), "occurred_at") if isinstance(e.get("occurred_at"), str) else None
            if isinstance(odt, datetime.datetime) and odt <= dt_to:
                scoped2.append(e)
        scoped = scoped2
    if afterSequence is not None:
        scoped = [e for e in scoped if isinstance(e.get("sequence"), int) and e["sequence"] > afterSequence]

    # Sort by sequence
    scoped.sort(key=lambda e: e.get("sequence", 0), reverse=(sortOrder == "desc"))

    # Cursor handling: treat as "offset" encoded as an int string; if invalid, ignore (opaque)
    start = 0
    next_cursor = None
    if cursor:
        try:
            start = int(cursor)
            if start < 0:
                start = 0
        except ValueError:
            start = 0

    page = scoped[start:start + limit]
    has_more = start + limit < len(scoped)
    if has_more:
        next_cursor = str(start + limit)

    _log(api_requests, integ_row["id"], "ok", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)

    return {
        "deploymentId": deploymentId,
        "integrationId": integ_row["id"],
        "events": page,
        "pagination": {
            "total": len(scoped),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor,
        },
    }

def getDeployment(deploymentId, integrationId=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0117000" if __import__("os").path.isdir("./environment_mix/0117000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    def _match_id(pat, val):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _log(api_requests, integration_id, tool_name, request_params, deployment_id=None,
             status="ok", http_status=None, error_code=None, error_message=None, latency_ms=None):
        rid = "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=")
        row = {
            "id": rid,
            "integration_id": integration_id,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "deployment_id": deployment_id,
            "deployment_file_id": None,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) and latency_ms >= 0 else None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return row

    def _resolve_active_integration(vercel_integrations, requested_id):
        if requested_id is not None:
            if not _match_id(r"^vint_[0-9A-Z]{17,}$", requested_id):
                return None, _err("VALIDATION_ERROR", "Invalid integrationId.")
            for r in vercel_integrations:
                if r.get("id") == requested_id and r.get("status") == "active":
                    return r, None
            return None, _err("UNAUTHORIZED", "No active integration available for this request scope.")
        for r in vercel_integrations:
            if r.get("status") == "active":
                return r, None
        return None, _err("UNAUTHORIZED", "No active integration available.")

    if not _match_id(r"^dpl_[0-9A-Z]{17,}$", deploymentId):
        vercel_integrations = _load("vercel_integrations.json")
        api_requests = _load("api_requests.json")
        integ, _ = _resolve_active_integration(vercel_integrations, integrationId)
        integ_id = integ["id"] if integ else (integrationId if isinstance(integrationId, str) else "unknown")
        _log(api_requests, integ_id, "getDeployment",
             {"deploymentId": deploymentId, "integrationId": integrationId},
             deployment_id=None, status="error", http_status=400, error_code="VALIDATION_ERROR",
             error_message="Invalid deploymentId.", latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid deploymentId.")

    vercel_integrations = _load("vercel_integrations.json")
    api_requests = _load("api_requests.json")
    integ, integ_err = _resolve_active_integration(vercel_integrations, integrationId)
    if integ_err:
        _log(api_requests, integrationId if isinstance(integrationId, str) else "unknown", "getDeployment",
             {"deploymentId": deploymentId, "integrationId": integrationId},
             deployment_id=deploymentId, status="error", http_status=401, error_code=integ_err["error"]["code"],
             error_message=integ_err["error"]["message"], latency_ms=(time.time() - t0) * 1000)
        return integ_err
    integration_id = integ["id"]

    # Rate limiting (simple local policy): 120/min per integration+tool, 20k/day per integration+tool
    tool = "getDeployment"
    window_s = 60
    day_s = 86400
    per_minute = 120
    per_day = 20000

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    recent = 0
    daily = 0
    for r in api_requests:
        if r.get("integration_id") != integration_id or r.get("tool_name") != tool:
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            continue
        age = (now - dt).total_seconds()
        if 0 <= age <= window_s:
            recent += 1
        if 0 <= age <= day_s:
            daily += 1
    if recent >= per_minute or daily >= per_day:
        _log(api_requests, integration_id, tool,
             {"deploymentId": deploymentId, "integrationId": integrationId},
             deployment_id=deploymentId, status="rate_limited", http_status=429,
             error_code="RATE_LIMIT" if recent >= per_minute else "QUOTA_EXCEEDED",
             error_message="Rate limit exceeded." if recent >= per_minute else "Daily quota exceeded.",
             latency_ms=(time.time() - t0) * 1000)
        return _err("RATE_LIMIT" if recent >= per_minute else "QUOTA_EXCEEDED",
                    "Rate limit exceeded." if recent >= per_minute else "Daily quota exceeded.")

    deployments = _load("deployments.json")
    dep = None
    for d in deployments:
        if d.get("id") == deploymentId and d.get("integration_id") == integration_id:
            dep = d
            break

    # Upstream fetch attempt: offline implementation cannot reach Vercel; do not fabricate.
    if dep is None:
        _log(api_requests, integration_id, tool,
             {"deploymentId": deploymentId, "integrationId": integrationId},
             deployment_id=deploymentId, status="error", http_status=404, error_code="NOT_FOUND",
             error_message="Deployment not found in cache (upstream fetch unavailable offline).",
             latency_ms=(time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Deployment not found.")

    _log(api_requests, integration_id, tool,
         {"deploymentId": deploymentId, "integrationId": integrationId},
         deployment_id=deploymentId, status="ok", http_status=200, latency_ms=(time.time() - t0) * 1000)
    return {"deployment": dep}

def listDeploymentFiles(deploymentId, integrationId=None, status=None, pathPrefix=None, contentType=None, encoding=None, storage=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
