    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_s = now_dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        raw = hashlib.sha1((prefix + ":" + now_s + ":" + str(time.time_ns())).encode("utf-8")).digest()
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s[:20]}"

    def _match_id(pat, val):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _log(api_requests, integration_id, status_val, http_status=None, error_code=None, error_message=None, deployment_id=None, latency_ms=None):
        row = {
            "id": _new_id("req"),
            "integration_id": integration_id,
            "tool_name": "listDeploymentFiles",
            "request_params": {
                "deploymentId": deploymentId,
                "integrationId": integrationId,
                "status": status,
                "pathPrefix": pathPrefix,
                "contentType": contentType,
                "encoding": encoding,
                "storage": storage,
                "sortBy": sortBy,
                "sortOrder": sortOrder,
                "limit": limit,
                "cursor": cursor,
            },
            "deployment_id": deployment_id,
            "deployment_file_id": None,
            "status": status_val,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) and latency_ms >= 0 else None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return row

    # Validate
    if not _match_id(r"^dpl_[0-9A-Z]{17,}$", deploymentId):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="deploymentId is invalid.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "deploymentId is invalid.")

    if integrationId is not None and not _match_id(r"^vint_[0-9A-Z]{17,}$", integrationId):
        reqs = _load("api_requests.json")
        _log(reqs, "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="integrationId is invalid.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "integrationId is invalid.")

    if status is not None and status not in ("listed", "fetching", "available", "unavailable", "deleted"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="status is invalid.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "status is invalid.")

    if pathPrefix is not None and not isinstance(pathPrefix, str):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="pathPrefix must be a string.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "pathPrefix must be a string.")

    if contentType is not None and not isinstance(contentType, str):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="contentType must be a string.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "contentType must be a string.")

    if encoding is not None and encoding not in ("none", "gzip"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="encoding is invalid.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "encoding is invalid.")

    if storage is not None and storage not in ("inline", "blob"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="storage is invalid.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "storage is invalid.")

    if sortBy is None:
        sortBy = "path"
    if sortBy not in ("path", "size_bytes", "listed_at", "fetched_at", "created_at", "updated_at"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="sortBy is invalid.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "sortBy is invalid.")

    if sortOrder is None:
        sortOrder = "asc"
    if sortOrder not in ("asc", "desc"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="sortOrder is invalid.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "sortOrder is invalid.")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 500.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")

    if cursor is not None and not isinstance(cursor, str):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="cursor must be a string.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Resolve active integration context; prefer the requested one if valid+active, else find one owning deployment.
    integrations = _load("vercel_integrations.json")
    active = [r for r in integrations if isinstance(r, dict) and r.get("status") == "active"]

    deployments = _load("deployments.json")
    dep = None
    integ_row = None

    if integrationId is not None:
        integ_row = next((r for r in active if r.get("id") == integrationId), None)
        if integ_row:
            dep = next((d for d in deployments if isinstance(d, dict) and d.get("id") == deploymentId and d.get("integration_id") == integ_row["id"]), None)
    else:
        active_ids = {r.get("id") for r in active if isinstance(r.get("id"), str)}
        dep = next((d for d in deployments if isinstance(d, dict) and d.get("id") == deploymentId and d.get("integration_id") in active_ids), None)
        if dep:
            integ_row = next((r for r in active if r.get("id") == dep.get("integration_id")), None)

    api_requests = _load("api_requests.json")
    if not integ_row:
        _log(api_requests, integrationId if isinstance(integrationId, str) else "vint_UNKNOWN", "error", error_code="UNAUTHORIZED", error_message="No active integration available for this call.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No active integration available for this call.")
    if not dep:
        _log(api_requests, integ_row["id"], "error", error_code="NOT_FOUND", error_message="Deployment not found in this integration scope.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Deployment not found in this integration scope.")

    files = _load("deployment_files.json")
    rows = [f for f in files if isinstance(f, dict) and f.get("deployment_id") == deploymentId and f.get("integration_id") == integ_row["id"]]

    # If missing, real service may backfill from upstream; offline we return empty list (not error).
    if status is not None:
        rows = [f for f in rows if f.get("status") == status]
    if pathPrefix is not None:
        rows = [f for f in rows if isinstance(f.get("path"), str) and f["path"].startswith(pathPrefix)]
    if contentType is not None:
        rows = [f for f in rows if f.get("content_type") == contentType]
    if encoding is not None:
        rows = [f for f in rows if f.get("encoding") == encoding]
    if storage is not None:
        rows = [f for f in rows if f.get("storage") == storage]

    # Sort
    def _key(v):
        x = v.get(sortBy)
        return (x is None, x)

    rows.sort(key=_key, reverse=(sortOrder == "desc"))

    # Cursor as offset integer string
    start = 0
    if cursor:
        try:
            start = int(cursor)
            if start < 0:
                start = 0
        except ValueError:
            start = 0

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = str(start + limit) if has_more else None

    _log(api_requests, integ_row["id"], "ok", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)

    return {
        "deploymentId": deploymentId,
        "integrationId": integ_row["id"],
        "files": page,
        "pagination": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "cursor": cursor},
    }

def getDeployments(integrationId=None, vercelProjectId=None, projectName=None, target=None, source=None, status=None, createdBy=None, gitRepo=None, gitRef=None, commitSha=None, createdAtFrom=None, createdAtTo=None, updatedAtFrom=None, updatedAtTo=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0117000" if __import__("os").path.isdir("./environment_mix/0117000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    integrations = _load("vercel_integrations.json")
    deployments = _load("deployments.json")
    reqs = _load("api_requests.json")

    def _new_id(prefix):
        raw = hashlib.sha1((prefix + ":" + now_s + ":" + str(time.time_ns())).encode("utf-8")).digest()
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s[:20]}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(integration_row, status_s, http_status=None, error_code=None, error_message=None, latency_ms=None):
        row = {
            "id": _new_id("req"),
            "integration_id": integration_row["id"] if integration_row else "vint_UNKNOWN",
            "tool_name": "getDeployments",
            "request_params": {
                "integrationId": integrationId,
                "vercelProjectId": vercelProjectId,
                "projectName": projectName,
                "target": target,
                "source": source,
                "status": status,
                "createdBy": createdBy,
                "gitRepo": gitRepo,
                "gitRef": gitRef,
                "commitSha": commitSha,
                "createdAtFrom": createdAtFrom,
                "createdAtTo": createdAtTo,
                "updatedAtFrom": updatedAtFrom,
                "updatedAtTo": updatedAtTo,
                "sortBy": sortBy,
                "sortOrder": sortOrder,
                "limit": limit,
                "cursor": cursor,
            },
            "deployment_id": None,
            "deployment_file_id": None,
            "status": status_s,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    def _active_integration_for_request():
        active = [r for r in integrations if isinstance(r, dict) and r.get("status") == "active"]
        if integrationId is not None:
            if not isinstance(integrationId, str) or not re.match(r"^vint_[0-9A-Z]{17,}$", integrationId):
                return None, _err("VALIDATION_ERROR", "integrationId is invalid.")
            active = [r for r in active if r.get("id") == integrationId]
        if len(active) != 1:
            return None, _err("UNAUTHORIZED", "No active integration context available for this call.")
        return active[0], None

    def _check_rate_limit(integration_row):
        # Simple local rate limit: 120 calls per 60s per tool+integration
        window_s = 60
        limit_n = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_id") != integration_row["id"]:
                continue
            if r.get("tool_name") != "getDeployments":
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        return cnt < limit_n

    try:
        # Validate enums/types
        if vercelProjectId is not None and not isinstance(vercelProjectId, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "vercelProjectId must be a string.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "vercelProjectId must be a string.")
        if projectName is not None and not isinstance(projectName, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "projectName must be a string.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "projectName must be a string.")
        if target is not None and target not in ("production", "preview", "development"):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "target is invalid.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "target is invalid.")
        if source is not None and source not in ("git", "cli", "import", "unknown"):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "source is invalid.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "source is invalid.")
        if status is not None and status not in ("queued", "building", "ready", "error", "canceled", "deleted"):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "status is invalid.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "status is invalid.")
        if createdBy is not None and not isinstance(createdBy, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "createdBy must be a string.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "createdBy must be a string.")
        if gitRepo is not None and not isinstance(gitRepo, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "gitRepo must be a string.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "gitRepo must be a string.")
        if gitRef is not None and not isinstance(gitRef, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "gitRef must be a string.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "gitRef must be a string.")
        if commitSha is not None and not isinstance(commitSha, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "commitSha must be a string.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "commitSha must be a string.")

        dt_created_from = _parse_dt(createdAtFrom)
        dt_created_to = _parse_dt(createdAtTo)
        dt_updated_from = _parse_dt(updatedAtFrom)
        dt_updated_to = _parse_dt(updatedAtTo)
        if createdAtFrom is not None and dt_created_from is None:
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "createdAtFrom must be RFC3339 date-time.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "createdAtFrom must be RFC3339 date-time.")
        if createdAtTo is not None and dt_created_to is None:
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "createdAtTo must be RFC3339 date-time.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "createdAtTo must be RFC3339 date-time.")
        if updatedAtFrom is not None and dt_updated_from is None:
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "updatedAtFrom must be RFC3339 date-time.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "updatedAtFrom must be RFC3339 date-time.")
        if updatedAtTo is not None and dt_updated_to is None:
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "updatedAtTo must be RFC3339 date-time.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "updatedAtTo must be RFC3339 date-time.")

        if dt_created_from and dt_created_to and dt_created_from > dt_created_to:
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "createdAtFrom must be <= createdAtTo.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "createdAtFrom must be <= createdAtTo.")
        if dt_updated_from and dt_updated_to and dt_updated_from > dt_updated_to:
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "updatedAtFrom must be <= updatedAtTo.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "updatedAtFrom must be <= updatedAtTo.")

        if sortBy is not None and sortBy not in ("created_at", "updated_at", "started_at", "ready_at"):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "sortBy is invalid.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "sortBy is invalid.")
        if sortOrder is not None and sortOrder not in ("asc", "desc"):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "sortOrder is invalid.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "sortOrder is invalid.")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                integ, _ = _active_integration_for_request()
                _log(integ, "error", 400, "VALIDATION_ERROR", "limit must be an integer between 1 and 200.", (time.time() - t0) * 1000)
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        if cursor is not None and not isinstance(cursor, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "cursor must be a string.", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "cursor must be a string.")

        integ, auth_err = _active_integration_for_request()
        if auth_err:
            _log(None, "error", 401, auth_err["error"]["code"], auth_err["error"]["message"], (time.time() - t0) * 1000)
            return auth_err

        if not _check_rate_limit(integ):
            _log(integ, "rate_limited", 429, "RATE_LIMIT", "Rate limit exceeded.", (time.time() - t0) * 1000)
            return _err("RATE_LIMIT", "Rate limit exceeded.")

        # Base filter: scoped to integration_id and not deleted (unless explicitly requested with status='deleted')
        rows = [d for d in deployments if isinstance(d, dict) and d.get("integration_id") == integ["id"]]
        if status != "deleted":
            rows = [d for d in rows if d.get("status") != "deleted"]
        # Additional filters
        if vercelProjectId is not None:
            rows = [d for d in rows if d.get("vercel_project_id") == vercelProjectId]
        if projectName is not None:
            rows = [d for d in rows if d.get("project_name") == projectName]
        if target is not None:
            rows = [d for d in rows if d.get("target") == target]
        if source is not None:
            rows = [d for d in rows if d.get("source") == source]
        if status is not None:
            rows = [d for d in rows if d.get("status") == status]
        if createdBy is not None:
            rows = [d for d in rows if d.get("created_by") == createdBy]
        if gitRepo is not None:
            rows = [d for d in rows if d.get("git_repo") == gitRepo]
        if gitRef is not None:
            rows = [d for d in rows if d.get("git_ref") == gitRef]
        if commitSha is not None:
            rows = [d for d in rows if d.get("commit_sha") == commitSha]

        def _dt_field(row, k):
            v = row.get(k)
            if v is None:
                return None
            if isinstance(v, str):
                return _parse_dt(v)
            return None

        if dt_created_from is not None:
            rows = [d for d in rows if (_dt_field(d, "created_at") is not None and _dt_field(d, "created_at") >= dt_created_from)]
        if dt_created_to is not None:
            rows = [d for d in rows if (_dt_field(d, "created_at") is not None and _dt_field(d, "created_at") <= dt_created_to)]
        if dt_updated_from is not None:
            rows = [d for d in rows if (_dt_field(d, "updated_at") is not None and _dt_field(d, "updated_at") >= dt_updated_from)]
        if dt_updated_to is not None:
            rows = [d for d in rows if (_dt_field(d, "updated_at") is not None and _dt_field(d, "updated_at") <= dt_updated_to)]

        # Sorting
        sb = sortBy or "created_at"
        so = sortOrder or "desc"
        def _sort_key(d):
            dv = _dt_field(d, sb)
            return dv if dv is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        rows.sort(key=_sort_key, reverse=(so == "desc"))

        # Cursor pagination: cursor = "<sortBy>:<iso>"
        start_idx = 0
        if cursor:
            # Find first row after cursor boundary
            parts = cursor.split(":", 1)
            if len(parts) == 2:
                c_field, c_val = parts[0], parts[1]
                if c_field != sb:
                    _log(integ, "error", 400, "VALIDATION_ERROR", "cursor does not match sortBy.", (time.time() - t0) * 1000)
                    return _err("VALIDATION_ERROR", "cursor does not match sortBy.")
                c_dt = _parse_dt(c_val)
                if c_dt is None:
                    _log(integ, "error", 400, "VALIDATION_ERROR", "cursor is invalid.", (time.time() - t0) * 1000)
                    return _err("VALIDATION_ERROR", "cursor is invalid.")
                # For desc: we already sorted desc, so skip while key >= c_dt (i.e., already seen)
                def _cmp(v):
                    return v if v is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                if so == "desc":
                    while start_idx < len(rows) and _cmp(_dt_field(rows[start_idx], sb)) >= c_dt:
                        start_idx += 1
                else:
                    while start_idx < len(rows) and _cmp(_dt_field(rows[start_idx], sb)) <= c_dt:
                        start_idx += 1
            else:
                _log(integ, "error", 400, "VALIDATION_ERROR", "cursor is invalid.", (time.time() - t0) * 1000)
                return _err("VALIDATION_ERROR", "cursor is invalid.")

        lim = limit or 50
        page = rows[start_idx:start_idx + lim]
        has_more = (start_idx + lim) < len(rows)
        next_cursor = None
        if has_more and page:
            last_dt = _dt_field(page[-1], sb)
            if last_dt is not None:
                next_cursor = f"{sb}:{last_dt.isoformat()}"

        _log(integ, "ok", 200, latency_ms=(time.time() - t0) * 1000)
        return {
            "data": {
                "deployments": page,
                "page": {
                    "total": len(rows),
                    "limit": lim,
                    "has_more": has_more,
                    "next_cursor": next_cursor,
                    "sort_by": sb,
                    "sort_order": so,
                },
            }
        }
    except Exception as e:
        integ, _ = _active_integration_for_request()
        _log(integ, "error", 500, "CONFLICT", str(e), (time.time() - t0) * 1000)
        return _err("CONFLICT", "Unexpected error.", detail=str(e))

def deleteDeployment(deploymentId, integrationId=None, reason=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0117000" if __import__("os").path.isdir("./environment_mix/0117000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    integrations = _load("vercel_integrations.json")
    deployments = _load("deployments.json")
    events = _load("deployment_events.json")
    reqs = _load("api_requests.json")

    def _new_id(prefix):
        raw = hashlib.sha1((prefix + ":" + now_s + ":" + str(time.time_ns())).encode("utf-8")).digest()
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s[:20]}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(integration_row, status, http_status=None, error_code=None, error_message=None, deployment_id=None, latency_ms=None):
        row = {
            "id": _new_id("req"),
            "integration_id": integration_row["id"] if integration_row else "vint_UNKNOWN",
            "tool_name": "deleteDeployment",
            "request_params": {"deploymentId": deploymentId, "integrationId": integrationId, "reason": reason},
            "deployment_id": deployment_id,
            "deployment_file_id": None,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    def _active_integration_for_request():
        active = [r for r in integrations if isinstance(r, dict) and r.get("status") == "active"]
        if integrationId is not None:
            if not isinstance(integrationId, str) or not re.match(r"^vint_[0-9A-Z]{17,}$", integrationId):
                return None, _err("VALIDATION_ERROR", "integrationId is invalid.")
            active = [r for r in active if r.get("id") == integrationId]
        if len(active) != 1:
            return None, _err("UNAUTHORIZED", "No active integration context available for this call.")
        return active[0], None

    def _check_rate_limit(integration_row):
        window_s = 60
        limit_n = 60
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_id") != integration_row["id"]:
                continue
            if r.get("tool_name") != "deleteDeployment":
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        return cnt < limit_n

    try:
        if not isinstance(deploymentId, str) or not re.match(r"^dpl_[0-9A-Z]{17,}$", deploymentId):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "deploymentId is invalid.", latency_ms=(time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "deploymentId is invalid.")
        if reason is not None and not isinstance(reason, str):
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "reason must be a string.", latency_ms=(time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "reason must be a string.")
        if isinstance(reason, str) and len(reason) > 500:
            integ, _ = _active_integration_for_request()
            _log(integ, "error", 400, "VALIDATION_ERROR", "reason is too long.", latency_ms=(time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "reason is too long.")

        integ, auth_err = _active_integration_for_request()
        if auth_err:
            _log(None, "error", 401, auth_err["error"]["code"], auth_err["error"]["message"], latency_ms=(time.time() - t0) * 1000)
            return auth_err

        if not _check_rate_limit(integ):
            _log(integ, "rate_limited", 429, "RATE_LIMIT", "Rate limit exceeded.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
            return _err("RATE_LIMIT", "Rate limit exceeded.")

        drow = next((d for d in deployments if isinstance(d, dict) and d.get("id") == deploymentId and d.get("integration_id") == integ["id"]), None)
        if not drow:
            _log(integ, "error", 404, "NOT_FOUND", "Deployment not found.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Deployment not found.")

        # Idempotent: if already deleted, return current row
        if drow.get("status") == "deleted":
            _log(integ, "ok", 200, deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
            return {"data": {"deployment": drow, "upstream": {"attempted": True, "http_status": 204, "result": "already_deleted"}}}

        # Enforce transition
        allowed = {
            "queued": ["building", "ready", "error", "canceled", "deleted"],
            "building": ["ready", "error", "canceled", "deleted"],
            "ready": ["deleted"],
            "error": ["deleted"],
            "canceled": ["deleted"],
            "deleted": [],
        }
        cur = drow.get("status")
        if cur not in allowed or "deleted" not in allowed[cur]:
            _log(integ, "error", 409, "INVALID_TRANSITION", "Deployment cannot be deleted from its current status.", deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
            return _err("INVALID_TRANSITION", "Deployment cannot be deleted from its current status.")

        drow["status"] = "deleted"
        drow["deleted_at"] = now_s
        drow["updated_at"] = now_s

        # Append audit event (sequence monotonic per deployment)
        dep_events = [e for e in events if isinstance(e, dict) and e.get("deployment_id") == deploymentId and e.get("integration_id") == integ["id"]]
        max_seq = 0
        for e in dep_events:
            try:
                s = int(e.get("sequence"))
                if s > max_seq:
                    max_seq = s
            except Exception:
                pass
        new_seq = max_seq + 1 if max_seq >= 1 else 1
        ev = {
            "id": _new_id("evt"),
            "deployment_id": deploymentId,
            "integration_id": integ["id"],
            "sequence": new_seq,
            "event_type": "audit",
            "level": "info",
            "message": "Deployment deleted." + (f" Reason: {reason}" if reason else ""),
            "payload": {"action": "delete", "reason": reason} if reason else {"action": "delete"},
            "occurred_at": now_s,
            "created_at": now_s,
            "updated_at": now_s,
        }
        events.append(ev)

        _save("deployments.json", deployments)
        _save("deployment_events.json", events)

        # Attempt upstream deletion: simulated outcome
        upstream_http = 204

        _log(integ, "ok", upstream_http, deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return {"data": {"deployment": drow, "event": ev, "upstream": {"attempted": True, "http_status": upstream_http, "result": "deleted"}}}
    except Exception as e:
        integ, _ = _active_integration_for_request()
        _log(integ, "error", 500, "CONFLICT", str(e), deployment_id=deploymentId, latency_ms=(time.time() - t0) * 1000)
        return _err("CONFLICT", "Unexpected error.", detail=str(e))

def updateVercelIntegration(integrationId, status=None, accessToken=None, tokenExpiresAt=None, lastSyncCursor=None, lastSyncAt=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0117000" if __import__("os").path.isdir("./environment_mix/0117000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_s = now_dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        raw = hashlib.sha1((prefix + ":" + now_s + ":" + str(time.time_ns())).encode("utf-8")).digest()
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s[:20]}"

    def _match_id(pat, val):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            v = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _log(api_requests, integration_id, status_val, http_status=None, error_code=None, error_message=None, latency_ms=None):
        row = {
            "id": _new_id("req"),
            "integration_id": integration_id,
            "tool_name": "updateVercelIntegration",
            "request_params": {
                "integrationId": integrationId,
                "status": status,
                "accessToken": ("***" if isinstance(accessToken, str) else accessToken),
                "tokenExpiresAt": tokenExpiresAt,
                "lastSyncCursor": lastSyncCursor,
                "lastSyncAt": lastSyncAt,
            },
            "deployment_id": None,
            "deployment_file_id": None,
            "status": status_val,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) and latency_ms >= 0 else None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return row

    # Validate
    if not _match_id(r"^vint_[0-9A-Z]{17,}$", integrationId):
        reqs = _load("api_requests.json")
        _log(reqs, "vint_UNKNOWN", "error", error_code="VALIDATION_ERROR", error_message="integrationId is invalid.", latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "integrationId is invalid.")

    if status is not None and status not in ("active", "revoked", "error", "disabled"):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId, "error", error_code="VALIDATION_ERROR", error_message="status is invalid.", latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "status is invalid.")

    if accessToken is not None and (not isinstance(accessToken, str) or len(accessToken) < 10):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId, "error", error_code="VALIDATION_ERROR", error_message="accessToken must be a string of length >= 10.", latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "accessToken must be a string of length >= 10.")

    exp = None
    if tokenExpiresAt is not None:
        exp = _parse_dt(tokenExpiresAt, "tokenExpiresAt")
        if isinstance(exp, dict) and "error" in exp:
            reqs = _load("api_requests.json")
            _log(reqs, integrationId, "error", error_code="VALIDATION_ERROR", error_message=exp["error"]["message"], latency_ms=(time.time() - t0) * 1000)
            return exp

    if lastSyncCursor is not None and not isinstance(lastSyncCursor, str):
        reqs = _load("api_requests.json")
        _log(reqs, integrationId, "error", error_code="VALIDATION_ERROR", error_message="lastSyncCursor must be a string.", latency_ms=(time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "lastSyncCursor must be a string.")

    last_sync_at_val = None
    if lastSyncAt is not None:
        last_sync_at_val = _parse_dt(lastSyncAt, "lastSyncAt")
        if isinstance(last_sync_at_val, dict) and "error" in last_sync_at_val:
            reqs = _load("api_requests.json")
            _log(reqs, integrationId, "error", error_code="VALIDATION_ERROR", error_message=last_sync_at_val["error"]["message"], latency_ms=(time.time() - t0) * 1000)
            return last_sync_at_val

    integrations = _load("vercel_integrations.json")
    row = next((r for r in integrations if isinstance(r, dict) and r.get("id") == integrationId), None)

    api_requests = _load("api_requests.json")

    if not row:
        _log(api_requests, integrationId, "error", error_code="NOT_FOUND", error_message="Integration not found.", latency_ms=(time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Integration not found.")

    # Enforce lifecycle transitions if status change requested
    transitions = {
        "active": ("error", "disabled", "revoked"),
        "error": ("active", "disabled", "revoked"),
        "disabled": ("active", "revoked"),
        "revoked": (),
    }
    if status is not None:
        cur = row.get("status")
        if cur not in transitions:
            _log(api_requests, integrationId, "error", error_code="CONFLICT", error_message="Integration has an invalid current status.", latency_ms=(time.time() - t0) * 1000)
            return _err("CONFLICT", "Integration has an invalid current status.")
        if status != cur and status not in transitions[cur]:
            _log(api_requests, integrationId, "error", error_code="INVALID_TRANSITION", error_message=f"Illegal status transition {cur} -> {status}.", latency_ms=(time.time() - t0) * 1000)
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.")
        row["status"] = status

    # Default validation: if no status transition requested, integration must be active
    if status is None and row.get("status") != "active":
        _log(api_requests, integrationId, "error", error_code="UNAUTHORIZED", error_message="Integration is not active.", latency_ms=(time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Integration is not active.")

    # Rotate credentials
    if accessToken is not None:
        row["access_token_last4"] = accessToken[-4:]
        row["access_token_ciphertext"] = "enc:" + base64.b64encode(accessToken.encode("utf-8")).decode("ascii")
        row["token_expires_at"] = exp  # can be None

        # For PAT, store null expiry per schema
        if row.get("auth_type") == "pat":
            row["token_expires_at"] = None

    elif tokenExpiresAt is not None:
        # allow updating expiry without rotating token
        row["token_expires_at"] = exp
        if row.get("auth_type") == "pat":
            row["token_expires_at"] = None

    # Sync state updates (assume caller is permitted in this offline surface)
    if lastSyncCursor is not None:
        row["last_sync_cursor"] = lastSyncCursor
    if last_sync_at_val is not None:
        row["last_sync_at"] = last_sync_at_val

    row["updated_at"] = now_s
    _save("vercel_integrations.json", integrations)

    _log(api_requests, integrationId, "ok", latency_ms=(time.time() - t0) * 1000)

    out = dict(row)
    out.pop("access_token_ciphertext", None)
    return {"integration": out}

def getCallerContext(integrationId=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0117000" if __import__("os").path.isdir("./environment_mix/0117000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        raw = hashlib.sha256(f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")).digest()
        out = []
        for b in raw:
            out.append(alphabet[b % len(alphabet)])
            if len(out) >= 18:
                break
        return f"{prefix}_{''.join(out)}"

    def _log_request(integration_id, req_params, status_val="ok", http_status=None, error_code=None, error_message=None, latency_ms=None):
        rows = _load("api_requests.json")
        row = {
            "id": _new_id("req"),
            "integration_id": integration_id,
            "tool_name": "getCallerContext",
            "request_params": req_params if isinstance(req_params, dict) else {},
            "deployment_id": None,
            "deployment_file_id": None,
            "status": status_val,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now,
            "updated_at": now,
        }
        rows.append(row)
        _save("api_requests.json", rows)

    # Validate
    if integrationId is not None:
        if not isinstance(integrationId, str) or not re.match(r"^vint_[0-9A-Z]{17,}$", integrationId):
            # best-effort log against any active integration
            integrations = _load("vercel_integrations.json")
            active_any = next((x for x in integrations if x.get("status") == "active"), None)
            if active_any:
                latency = int((time.time() - t0) * 1000)
                _log_request(active_any.get("id"), {"integrationId": integrationId}, status_val="error", http_status=400, error_code="VALIDATION_ERROR", error_message="integrationId is invalid", latency_ms=latency)
            return _err("VALIDATION_ERROR", "integrationId is invalid")

    integrations = _load("vercel_integrations.json")
    active = [x for x in integrations if x.get("status") == "active"]

    # Resolve context
    ctx = None
    if integrationId is None:
        if len(active) == 1:
            ctx = active[0]
        elif len(active) == 0:
            return _err("UNAUTHORIZED", "No active integration can be resolved")
        else:
            # ambiguous
            # cannot log without resolved integration per schema constraint; pick none -> UNAUTHORIZED
            return _err("UNAUTHORIZED", "Ambiguous caller context: multiple active integrations; specify integrationId")
    else:
        ctx = next((x for x in active if x.get("id") == integrationId), None)
        if not ctx:
            # if integration exists but not active, treat as UNAUTHORIZED per rule
            exists = next((x for x in integrations if x.get("id") == integrationId), None)
            if exists:
                # log against any active integration if present; otherwise cannot satisfy rule
                if active:
                    latency = int((time.time() - t0) * 1000)
                    _log_request(active[0].get("id"), {"integrationId": integrationId}, status_val="error", http_status=401, error_code="UNAUTHORIZED", error_message="Integration is not active", latency_ms=latency)
                return _err("UNAUTHORIZED", "Integration is not active")
            if active:
                latency = int((time.time() - t0) * 1000)
                _log_request(active[0].get("id"), {"integrationId": integrationId}, status_val="error", http_status=404, error_code="NOT_FOUND", error_message="Integration not found", latency_ms=latency)
            return _err("NOT_FOUND", "Integration not found")

    # Rate limit / quota consumption snapshot (best-effort, enabled with env toggles)
    def _count_recent(tool=None, window_seconds=60):
        rows = _load("api_requests.json")
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for r in rows:
            if r.get("integration_id") != ctx.get("id"):
                continue
            if tool is not None and r.get("tool_name") != tool:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                v = ca
                if v.endswith("Z"):
                    v = v[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(v)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except ValueError:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt

    # Compute before logging this call (so the returned "used" doesn't include itself)
    per_min = os.environ.get("VERCEL_RATE_LIMIT_PER_MINUTE")
    try:
        per_min = int(per_min) if per_min is not None else 60
    except ValueError:
        per_min = 60
    enabled = os.environ.get("VERCEL_RATE_LIMIT_ENABLED", "").lower() in ("1", "true", "yes", "on")

    tool_used_last_min = _count_recent(tool="getCallerContext", window_seconds=60)
    all_used_last_min = _count_recent(tool=None, window_seconds=60)

    # Log the call (must log every tool invocation)
    latency = int((time.time() - t0) * 1000)
    _log_request(ctx.get("id"), {"integrationId": integrationId}, status_val="ok", http_status=200, error_code=None, error_message=None, latency_ms=latency)

    safe = dict(ctx)
    safe.pop("access_token_ciphertext", None)

    # Granted scopes: not modeled in schema; return minimal stable set based on tool surface
    scopes = [
        "deployments:read",
        "deployments:write",
        "files:read",
        "events:read",
        "integration:read",
        "integration:write",
    ]

    return {
        "caller": {
            "type": "integration",
            "integration_id": ctx.get("id"),
            "vercel_team_id": ctx.get("vercel_team_id"),
            "vercel_user_id": ctx.get("vercel_user_id"),
            "auth_type": ctx.get("auth_type"),
            "token_last4": ctx.get("access_token_last4"),
        },
        "integration": safe,
        "scopes": scopes,
        "rate_limit": {
            "enabled": enabled,
            "limit_per_minute": per_min,
            "used_last_minute_all_tools": all_used_last_min,
            "used_last_minute_this_tool": tool_used_last_min,
            "remaining_this_minute_this_tool": max(0, per_min - tool_used_last_min),
        },
    }
